#!/usr/bin/env python3
"""Generate tiny FIGlet fonts for behavioral probing.

Usage: gen.py OUTFILE [options] glyphspec...
Options:
  --hardblank C    hardblank char (default $)
  --height N       height (default 3)
  --baseline N     (default height-1)
  --maxlen N       (default 20)
  --oldlayout N    old_layout header field (default -1)
  --comments N     comment lines (default 0)
  --printdir N     print_direction field; omit => old-style header (default: include as 0)
  --fulllayout N   full_layout field; requires --printdir
  --codetag N      codetag_count field
  --noheader-extra  write header with only 6 fields (no printdir etc.)
  --space W        width of space glyph (default 2)
glyphspec: C=row1,row2,...  (use . for blank, literal rows otherwise; rows padded with blanks to max row width of that glyph)
"""
import sys

def main():
    argv = sys.argv[1:]
    out = argv.pop(0)
    hardblank = '$'; height = 3; baseline = None; maxlen = 20
    oldlayout = -1; comments = 0; printdir = 0; fulllayout = None
    codetag = None; header_extra = True; spacewidth = 2
    glyphs = {}
    i = 0
    while i < len(argv):
        a = argv[i]
        if a.startswith('--'):
            opt = a[2:]
            if opt == 'noheader-extra':
                header_extra = False; i += 1; continue
            val = argv[i+1]; i += 2
            if opt == 'hardblank': hardblank = val
            elif opt == 'height': height = int(val)
            elif opt == 'baseline': baseline = int(val)
            elif opt == 'maxlen': maxlen = int(val)
            elif opt == 'oldlayout': oldlayout = int(val)
            elif opt == 'comments': comments = int(val)
            elif opt == 'printdir': printdir = int(val)
            elif opt == 'fulllayout': fulllayout = int(val)
            elif opt == 'codetag': codetag = int(val)
            elif opt == 'space': spacewidth = int(val)
            else: raise SystemExit('unknown opt ' + opt)
        else:
            ch, spec = a.split('=', 1)
            rows = spec.split(',')
            w = max(len(r) for r in rows)
            rows = [r.replace('.', ' ').ljust(w) for r in rows]
            assert len(rows) == height, (ch, rows)
            glyphs[ch] = rows
            i += 1
    if baseline is None: baseline = height - 1
    hdr = 'flf2a%s %d %d %d %d %d' % (hardblank, height, baseline, maxlen, oldlayout, comments)
    if header_extra:
        hdr += ' %d' % printdir
        if fulllayout is not None:
            hdr += ' %d' % fulllayout
            if codetag is not None:
                hdr += ' %d' % codetag
    lines = [hdr]
    lines += ['comment'] * comments
    # space glyph
    glyphs.setdefault(' ', [' ' * spacewidth] * height)
    for code in range(32, 127):
        ch = chr(code)
        rows = glyphs.get(ch)
        if rows is None:
            rows = [''] * height  # zero-width glyph
        for j, r in enumerate(rows):
            end = '@@' if j == height - 1 else '@'
            lines.append(r + end)
    with open(out, 'w') as f:
        f.write('\n'.join(lines) + '\n')
    print('wrote', out)

main()

